import{_ as e,o as l,c as o,ak as t}from"./chunks/framework.DKi5cyCJ.js";const m=JSON.parse('{"title":"DMA","description":"Stream 与 Channel、NDTR、循环缓冲和启动顺序","frontmatter":{"title":"DMA","description":"Stream 与 Channel、NDTR、循环缓冲和启动顺序","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-DMA.md","filePath":"pages/blog/2026-10-20-DMA.md"}'),r={name:"pages/blog/2026-10-20-DMA.md"};function s(d,a,i,n,p,c){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="dma" tabindex="-1">DMA <a class="header-anchor" href="#dma" aria-label="Permalink to &quot;DMA&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a></p></blockquote><p>DMA 是总线主机。外设准备好一个数据后发出请求，DMA 在数据寄存器和内存之间搬运，CPU 不必为每个字节进中断。</p><p>STM32F405/F407 有 DMA1 和 DMA2，各 8 个 Stream。Channel 用来选择外设请求，选错时 Stream 能打开，NDTR 却不动。内存到内存只有 DMA2 支持。G4、H7 使用 DMAMUX，映射表不能混用。</p><p>NDTR 是数据个数，不是字节数。半字传输时 NDTR = 10 表示 20 字节。正常模式减到 0 就停。循环模式会自动重装，写指针是总长减去剩余 NDTR。</p><h2 id="启动顺序" tabindex="-1">启动顺序 <a class="header-anchor" href="#启动顺序" aria-label="Permalink to &quot;启动顺序&quot;">​</a></h2><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">关 Stream<br><small>等到 EN 清掉</small></div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">清全部标志</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">写地址和 NDTR</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node accent">使能 DMA<br><small>再开外设请求</small></div></div></div><p>Stream 还开着的时候写 NDTR，硬件会丢掉这次写。残留的完成标志会让中断刚打开就进入。</p><p>F407 上 USART1 发送是 DMA2 Stream7 Channel4，接收是 DMA2 Stream5 Channel4。方向 00 是外设到内存，01 是内存到外设。DMA 完成只说明最后一字节写进了数据寄存器，线上发完要等串口的 TC，再去关 RS485 的方向脚。</p><p>直接模式一次请求搬一个数据，两边宽度必须相同。突发要打开 FIFO。半传输中断用来处理缓冲区的另一半，处理时间不能超过半个周期。</p><p>H7 上不要把缓冲放在 DTCM。详见 <a href="/pages/blog/2026-10-20-Cache与DMA一致性.html">Cache 与 DMA</a>。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',12)])])}const h=e(r,[["render",s]]);export{m as __pageData,h as default};
